INSERT INTO tour_day (option_id, day_no, title, description) VALUES (193, 4, '큐본 공원·랄바그 식물원', '240에이크의 푸른 정원과 크리스탈 온실. 공연이나 전시 일정에 맞춰 관람 시간을 조정합니다.');
