INSERT INTO tour_day (option_id, day_no, title, description) VALUES (284, 1, '시애틀 도착', '인천에서 출발해 시애틀에 도착합니다(항공권 별도). 숙소에 짐을 풀고 가이드 미팅과 환영 안내, 가벼운 저녁 식사를 합니다.');
