INSERT INTO tour_day (option_id, day_no, title, description) VALUES (310, 2, '카르메네레 와인 탐방', '칠레의 대표 와인으로 프랑스 원산 포도 품종. 현지 가이드와 함께 대표 맛집과 시장을 돌며 점심과 간식을 맛봅니다.');
